SELECT count(*) AS records,(count(*) FILTER(WHERE r.training_session_id IS NOT NULL AND s.id IS NULL)) AS missing_parent,(count(*) FILTER(WHERE s.id IS NOT NULL AND s.athlete_id IS DISTINCT FROM r.athlete_id)) AS owner_mismatch,(count(*) FILTER(WHERE s.id IS NOT NULL AND r.source_protocol_id IS NOT NULL AND r.source_protocol_id IS DISTINCT FROM s.protocol_id)) AS known_protocol_mismatch,(count(*) FILTER(WHERE r.record_id IS NOT NULL AND r.training_session_id IS NULL)) AS independent_parent_free FROM public.training_session_records r LEFT JOIN public.training_sessions s ON s.id=r.training_session_id;
